import {BUILD_STEPS,buildRoute,skipsLamination} from './downstream.js';
import {deliveryResults} from './delivery.js';
import {dateStr} from './model.js';
import {yearEndDate,yearEndOutlook} from './delivery-year-end.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=n=>Number(n||0).toLocaleString('en-US'),d=x=>x?new Date(x+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'—';
export function deliveryView(s,rows,filter,search){
 const cutoff=yearEndDate(s.settings.start),all=deliveryResults(rows).filter(o=>o.inPlan).map(o=>({...o,yearEnd:yearEndOutlook(o,s.settings.end,cutoff)})),critical=all.filter(o=>o.priority==='critical'),late=all.filter(o=>o.tone==='red'),good=all.filter(o=>o.projected&&!o.partial&&o.lateDays===0),missing=all.filter(o=>o.lead==null);
 const lateFinished=all.filter(o=>o.yearEnd.key==='lateByYearEnd'),unfinished=all.filter(o=>o.yearEnd.key==='notByYearEnd'),unknown=all.filter(o=>o.yearEnd.key==='yearEndUnknown');
 const visible=all.filter(o=>(filter==='all'||filter==='critical'&&o.priority==='critical'||filter==='late'&&o.tone==='red'||filter===o.yearEnd.key||filter==='lead'&&o.lead==null)&&(!search||`${o.part} ${o.week}`.toLowerCase().includes(search.toLowerCase())));
 return `<section class="delivery-intro"><span class="eyebrow">ORDER COMMITMENTS</span><h2>Protect the orders that matter most.</h2><p>Each product/week is one order group. Critical groups receive forming priority and reserve available Akro within 28 days of their Akro-needed date. Other demand uses the remaining stock. Customer-agreed dates move that group’s demand; the original due date stays visible. These are temporary exceptions; new groups remain Standard.</p></section>
 <div class="delivery-stats"><div class="card"><span>Critical order groups</span><strong>${critical.length}</strong><small>${critical.filter(o=>o.ready&&!o.partial).length} Akro covered · ${critical.filter(o=>o.lead==null).length} need lead time · ${critical.filter(o=>o.tone==='red').length} late</small></div><div class="card"><span>Ready by target</span><strong class="green-text">${good.length}</strong><small>Includes customer-agreed later dates</small></div><div class="card"><span>Late · finishes by Dec. 31</span><strong class="amber-text">${lateFinished.length}</strong><small>Projected ready to ship this year</small><button data-deliveryfilter="lateByYearEnd">View these orders →</button></div><div class="card"><span>Not completed by Dec. 31</span><strong class="red-text">${unfinished.length}</strong><small>Ready after year end or still unfilled</small><button data-deliveryfilter="notByYearEnd">View these orders →</button></div></div>
 <div class="year-end-summary"><span>Year-end cutoff: <strong>${d(cutoff)}, ${cutoff.slice(0,4)}</strong> · Based on when the whole order is ready to ship.</span><button data-deliveryfilter="yearEndUnknown">${unknown.length} year-end unconfirmed →</button>${s.settings.end<cutoff?'<span>Unfilled orders need a plan through Dec. 31 before a year-end conclusion can be made.</span>':''}</div>
 <section class="card delivery-card"><div class="toolbar"><div><h2 class="tabletitle">Order readiness outlook</h2><p>The whole order is ready to ship once the last batch clears QC. Production steps can overlap across batches. Shipment dates are scheduled separately.</p></div><button id="deliveryCsv">↓ Export order CSV</button></div><div class="delivery-controls"><label>Default remaining lead time · calendar days<input type="number" min="0" max="365" step="1" data-setting="deliveryLeadDays" aria-label="Default remaining lead time in calendar days" value="${s.settings.deliveryLeadDays??''}" placeholder="Enter to forecast readiness"></label><p>Calendar-day estimate from final Akro release to ready to ship, used when step times are incomplete. Review any allowance that included shipping. Enter 0 only if no further production time is needed.</p></div><div class="filter-bar"><div class="inline"><label class="filter-label">Show<select id="deliveryFilter" aria-label="Order readiness filter">${[['all','All orders'],['critical','Critical orders'],['late','All late / not covered'],['lateByYearEnd','Late · finishes by Dec. 31'],['notByYearEnd','Not completed by Dec. 31'],['yearEndUnknown','Year-end unconfirmed'],['lead','Need lead time']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="filter-label">Find<input id="deliverySearch" type="search" aria-label="Find order product or week" value="${esc(search)}" placeholder="Part number or week"></label></div><span class="small">${visible.length} groups · ${d(s.settings.start)} – ${d(s.settings.end)}</span></div>
 <div class="scroll"><table class="delivery-table"><thead><tr><th>Product / demand week</th><th>Quantity</th><th>Priority</th><th>Due / commitment</th><th>Akro coverage</th><th>Projected ready to ship</th><th>Readiness status</th><th>Year-end outlook</th><th></th></tr></thead><tbody>${visible.length?visible.map(o=>`<tr class="${o.priority==='critical'?'critical-order':''}"><td><strong>${esc(o.part)}</strong><small>${o.week} · ${o.kind==='thin'?'3/4"':'1 1/8"'}</small></td><td><strong>${f(o.cases)} cases</strong><small>${f(o.total)} whole sheets</small></td><td><select data-orderpriority="${o.partIndex}" data-week="${o.week}" aria-label="${esc(o.part)} ${o.week} priority"><option value="standard" ${o.priority==='standard'?'selected':''}>Standard</option><option value="critical" ${o.priority==='critical'?'selected':''}>Critical</option></select></td><td><strong>${d(o.due)}</strong><small>${o.accepted?`Agreed: ${d(o.accepted)}`:'Original due date'}</small><small>Akro needed: ${d(dateStr(o.needBy))}</small></td><td><strong>${o.ready?d(o.ready):'Not fully withdrawn'}</strong><small>${f(o.filled)} / ${f(o.total)} sheets released by plan end</small>${o.remaining?`<small class="red-text">${f(o.remaining)} sheets unfilled</small>`:''}</td><td><strong>${o.projected?d(o.projected):'—'}</strong><small>${o.lead==null?'Set remaining lead time':o.route.complete?`${o.route.total} working hours downstream`:`${o.lead}d after final Akro release`}</small></td><td><span class="badge ${o.tone}"><span class="status-dot"></span>${o.label}</span>${o.originalLateDays?`<small class="original-late">${o.lead==null?'At least ':''}${o.originalLateDays}d after original due</small>`:''}${o.partial?'<small>Earlier Akro demand carried to plan start; extend the start date to assess the full history.</small>':''}</td><td><span class="badge ${o.yearEnd.tone}"><span class="status-dot"></span>${o.yearEnd.label}</span><small>${esc(o.yearEnd.reason)}</small></td><td><button data-editorder="${o.partIndex}" data-week="${o.week}" aria-label="Edit ${esc(o.part)} ${o.week} delivery">Edit</button></td></tr>`).join(''):'<tr><td colspan="9" class="empty-state">No order groups match. Clear the filter or extend the plan dates.</td></tr>'}</tbody></table></div>
 <p class="table-footnote">Week-end Sunday is the default due date; use Edit for the actual commitment. Complete routes withdraw one 20-sheet batch when waterjet can take it, starting from their planned first-transfer date; Critical orders can start earlier within their 28-day priority window. The final order remainder uses whole sheets. Other routes retain the seven-day demand allocation. Stock and closure limits apply. Critical reservations remain in closing stock until released. A priority flag cannot create additional capacity or guarantee readiness.</p><details><summary>How readiness is assessed</summary><p>Akro-needed date = agreed later date (if entered), otherwise original due date, minus remaining lead time. For incomplete routes, projected readiness = final Akro release + the remaining calendar-day allowance. For complete routes, projected readiness is when the final batch clears QC. With incomplete step times, remaining lead time is a calendar-day allowance. With all effective step times entered, backward batch planning sets the Akro transfer dates and the forward forecast queues 20-sheet batches through one shared lane per step, using 10-hour shifts, holidays and waterjet shutdowns. Different steps can overlap. Orders with missing step times do not reserve downstream capacity; their readiness remains unconfirmed unless a calendar-day allowance is entered. Confirm actual completion and shipment separately. A customer-agreed extension never erases lateness against the original due date.</p><p>Orders due on or after plan start stay included even when their Akro-needed date falls before it. Earlier Akro demand is carried into day one as waiting demand. Orders with a readiness target before plan start remain outside the plan. A partial horizon is not treated as a complete on-time order. Extend the start/end dates to cover the full Akro transfer window and any delayed catch-up. Separate work orders for the same product and week are combined; weekly quantities are not added again here.</p></details></section>`;
}
export function orderEditor(s,partIndex,week){
 const p=s.parts[partIndex],m=p.delivery?.[week]||{},w=s.weeks.find(w=>w.key===week),date=new Date(w.date+'T00:00Z');date.setUTCDate(date.getUTCDate()+6);const due=m.due||date.toISOString().slice(0,10);const stepDefaults=buildRoute(s,p,week,{ignoreOrderOverrides:true}).hours;
 return `<h2>${esc(p.id)} · ${week}</h2><p>Update this product/week group. Quantities stay in Weekly demand.</p><p id="orderError" role="alert" class="red-text" hidden></p><div class="order-edit-fields"><label>Original due date<input id="orderDue" type="date" value="${due}"></label><label>Customer-agreed later date · optional<input id="orderAccepted" type="date" min="${due}" value="${m.accepted||''}"></label><label>Remaining lead time · calendar days<input id="orderLead" type="number" min="0" max="365" step="1" value="${m.leadDays??''}" placeholder="${s.settings.deliveryLeadDays==null?'Default not set':`Default: ${s.settings.deliveryLeadDays} days`}"></label><label>Notes / customer agreement<textarea id="orderNotes" rows="3" placeholder="Record the agreement or reason for this exception">${esc(m.notes||'')}</textarea></label></div><details class="order-step-settings"><summary>Step times · optional order overrides</summary><p>Working hours per whole order, using 10-hour operating days. Enter 0 to bypass a step. These overrides are total hours for this whole order. Blank uses the quantity-scaled product batch time, then any earlier whole-order allowance. A complete set replaces the calendar-day allowance and accounts for holidays and waterjet shutdowns.</p><div class="step-hour-grid">${BUILD_STEPS.map(([key,label])=>`<label>${label}<input id="orderStep-${key}" aria-label="${label} order working hours" type="number" min="0" max="3650" step="0.1" value="${key==='lamination'&&skipsLamination(p)?0:m.stepHours?.[key]??''}" ${key==='lamination'&&skipsLamination(p)?'disabled':''} placeholder="${stepDefaults?.[key]==null?'Product time not set':`Inherited: ${stepDefaults[key]} hours`}"></label>`).join('')}</div></details><p>Leave the per-order lead time blank to use the default. A later date shifts planning for this group and keeps the original commitment visible.</p><button class="primary" id="saveOrder" data-part="${partIndex}" data-week="${week}">Save order settings</button>`;
}
export function orderCsv(rows){const cutoff=yearEndDate(rows[0].date),end=rows.at(-1).date;const c=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [['Part','Week','Cases','Panels','Priority','Original_due','Agreed_later_date','Remaining_lead_days','Akro_needed','Akro_released_by_plan_end','Panels_unfilled','Akro_ready','Projected_ready_to_ship','Status','Days_after_original_due','Year_end_cutoff','Year_end_outlook'],...deliveryResults(rows).filter(o=>o.inPlan).map(o=>[o.part,o.week,o.cases,o.total,o.priority,o.due,o.accepted,o.lead,dateStr(o.needBy),o.filled,o.remaining,o.ready,o.projected,o.label,o.originalLateDays,cutoff,yearEndOutlook(o,end,cutoff).label])].map(r=>r.map(c).join(',')).join('\n')}
